(()=>{const supported=new Set(['he','en','ru','ar']);const pathParts=location.pathname.split('/').filter(Boolean);const pathLocale=supported.has(pathParts[0])?pathParts[0]:'he';window.__7yaLocale=pathLocale;window.__7yaCanonicalPath=()=>{const parts=location.pathname.split('/').filter(Boolean);if(supported.has(parts[0]))parts.shift();if(parts[parts.length-1]==='index.html')parts.pop();return '/'+(parts.length?parts.join('/')+'/':'')};window.__7yaLocalizePath=value=>{if(!value||typeof value!=='string'||!value.startsWith('/'))return value;let u;try{u=new URL(value,location.origin)}catch{return value}const parts=u.pathname.split('/').filter(Boolean);if(supported.has(parts[0]))parts.shift();if(parts[parts.length-1]==='index.html')parts.pop();const base='/'+(parts.length?parts.join('/')+'/':'');return (pathLocale==='he'?base:'/'+pathLocale+(base==='/'?'/':base))+u.search+u.hash};const url=new URL(location.href);const q=url.searchParams.get('lang');if(!supported.has(q))return;let parts=url.pathname.split('/').filter(Boolean);if(supported.has(parts[0]))parts.shift();if(parts[parts.length-1]==='index.html')parts.pop();const base='/'+(parts.length?parts.join('/')+'/':'');url.pathname=q==='he'?base:'/'+q+(base==='/'?'/':base);url.searchParams.delete('lang');location.replace(url.pathname+(url.searchParams.toString()?'?'+url.searchParams.toString():'')+url.hash)})();